> const axios = require("axios");
> const bodyParser = require("body-parser");
> const crypto = require("crypto");
> const app = express();
> app.use(bodyParser.json());
> 
> const LEDGER_URL = process.env.LEDGER_URL || "http://localhost:8546";
> const VISUAL_URL = process.env.VISUAL_URL || "http://localhost:7002";
