>   } catch (err) {
>     console.warn("ledger register failed:", err.message);
>   }
> 
>   // send to visual-listener
>   let vlResp = { confirm: false, confidence: 0.0 };
>   try {
>     const r = await axios.post(`${VISUAL_URL}/assess`, { thought }, { timeout: 8000 });
>     vlResp = r.data || vlResp;
>   } catch (err) {
>     console.warn("visual-listener call failed:", err.message);
>   }
> 
>   // return combined
